100 :          * F(mu - k * sig) <= p,
101 :          * and (mu - k * sig) is a lower-bound for the root.
102 :          *
103 :          * In cases where the Chebyshev inequality does not apply, geometric
104 :          * progressions 1, 2, 4, ... and -1, -2, -4, ... are used to bracket
105 :          * the root.
106 :          */
107 :         if (p < 0.0 || p > 1.0) {
108 :             throw new OutOfRangeException(p, 0, 1);
109 :         }
110 : 
111 :         double lowerBound = getSupportLowerBound();
112 :         if (p == 0.0) {
113 :             return lowerBound;
114 :         }
115 : 
116 :         double upperBound = getSupportUpperBound();
117 :         if (p == 1.0) {
118 :             return upperBound;
119 :         }
