121 :         final double mu = getNumericalMean();
122 :         final double sig = FastMath.sqrt(getNumericalVariance());
123 :         final boolean chebyshevApplies;
124 :         chebyshevApplies = !(Double.isInfinite(mu) || Double.isNaN(mu) ||
