127 :         if (lowerBound == Double.NEGATIVE_INFINITY) {
128 :             if (chebyshevApplies) {
129 :                 lowerBound = mu - sig * FastMath.sqrt((1. - p) / p);
130 :             } else {
131 :                 lowerBound = -1.0;
132 :                 while (cumulativeProbability(lowerBound) >= p) {
133 :                     lowerBound *= 2.0;
134 :                 }
135 :             }
136 :         }
