150 : 
151 :             public double value(final double x) {
152 :                 return cumulativeProbability(x) - p;
153 :             }
154 :         };
155 : 
156 :         double x = UnivariateSolverUtils.solve(toSolve,
157 :                                                    lowerBound,
158 :                                                    upperBound,
159 :                                                    getSolverAbsoluteAccuracy());
160 : 
161 :         if (!isSupportConnected()) {
162 :             /* Test for plateau. */
163 :             final double dx = getSolverAbsoluteAccuracy();
164 :             if (x - dx >= getSupportLowerBound()) {
165 :                 double px = cumulativeProbability(x);
166 :                 if (cumulativeProbability(x - dx) == px) {
167 :                     upperBound = x;
168 :                     while (upperBound - lowerBound > dx) {
169 :                         final double midPoint = 0.5 * (lowerBound + upperBound);
170 :                         if (cumulativeProbability(midPoint) < px) {
171 :                             lowerBound = midPoint;
172 :                         } else {
173 :                             upperBound = midPoint;
174 :                         }
175 :                     }
176 :                     return upperBound;
177 :                 }
178 :             }
179 :         }
